!function(e){"use strict";
  e('a.js-scroll-trigger[href*="#"]:not([href="#"])').click(function(){
    if(location.pathname.replace(/^\//,"")==this.pathname.replace(/^\//,"")&&location.hostname==this.hostname){
      var t=e(this.hash);
      if((t=t.length?t:e("[name="+this.hash.slice(1)+"]")).length)
        return e("html, body").animate({scrollTop:t.offset().top},1e3,"easeInOutExpo"),!1
    }
  }),
  e(".js-scroll-trigger").click(function(){e(".navbar-collapse").collapse("hide")}),
  e("body").scrollspy({target:"#sideNav"})

  // Typing Effect
  const titles = ["Backend Software Engineer", "Java Developer", "AWS Certified Developer", "Cloud Enthusiast"];
  let count = 0;
  let index = 0;
  let currentText = "";
  let letter = "";

  function type() {
    if (count === titles.length) {
      count = 0;
    }
    currentText = titles[count];
    letter = currentText.slice(0, ++index);

    const typingElement = document.querySelector(".typing");
    if (typingElement) {
      typingElement.textContent = letter;
    }

    if (letter.length === currentText.length) {
      setTimeout(() => {
        index = 0;
        count++;
        type();
      }, 2000);
    } else {
      setTimeout(type, 100);
    }
  }

  document.addEventListener("DOMContentLoaded", () => {
    if (document.querySelector(".typing")) {
      type();
    }
  });

}(jQuery);
